CREATE TABLE "knowledge_bases" ("id" TEXT PRIMARY KEY NOT NULL,"projectId" TEXT NOT NULL,"name" TEXT NOT NULL,"description" TEXT,"isDefault" BOOLEAN NOT NULL DEFAULT false,"retrievalConfig" JSONB NOT NULL,"indexVersion" INTEGER NOT NULL DEFAULT 0,"archivedAt" DATETIME,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" DATETIME NOT NULL);
CREATE INDEX "knowledge_bases_projectId_updatedAt_idx" ON "knowledge_bases"("projectId","updatedAt");
CREATE TABLE "knowledge_sources" ("id" TEXT PRIMARY KEY NOT NULL,"knowledgeBaseId" TEXT NOT NULL,"type" TEXT NOT NULL,"uri" TEXT,"displayName" TEXT NOT NULL,"config" JSONB NOT NULL,"status" TEXT NOT NULL DEFAULT 'pending',"contentHash" TEXT,"lastIndexedAt" DATETIME,"errorCode" TEXT,"archivedAt" DATETIME,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" DATETIME NOT NULL,CONSTRAINT "knowledge_sources_knowledgeBaseId_fkey" FOREIGN KEY ("knowledgeBaseId") REFERENCES "knowledge_bases"("id") ON DELETE CASCADE);
CREATE INDEX "knowledge_sources_knowledgeBaseId_updatedAt_idx" ON "knowledge_sources"("knowledgeBaseId","updatedAt");
CREATE TABLE "knowledge_documents" ("id" TEXT PRIMARY KEY NOT NULL,"sourceId" TEXT NOT NULL,"logicalPath" TEXT NOT NULL,"title" TEXT NOT NULL,"mimeType" TEXT NOT NULL,"contentHash" TEXT NOT NULL,"metadata" JSONB NOT NULL,"deletedAt" DATETIME,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" DATETIME NOT NULL,CONSTRAINT "knowledge_documents_sourceId_fkey" FOREIGN KEY ("sourceId") REFERENCES "knowledge_sources"("id") ON DELETE CASCADE);
CREATE UNIQUE INDEX "knowledge_documents_sourceId_logicalPath_key" ON "knowledge_documents"("sourceId","logicalPath");
CREATE TABLE "knowledge_chunks" ("id" TEXT PRIMARY KEY NOT NULL,"documentId" TEXT NOT NULL,"ordinal" INTEGER NOT NULL,"text" TEXT NOT NULL,"tokenCount" INTEGER NOT NULL,"headingPath" TEXT,"locator" JSONB NOT NULL,"contentHash" TEXT NOT NULL,"chunkerVersion" INTEGER NOT NULL,"indexVersion" INTEGER NOT NULL,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "knowledge_chunks_documentId_fkey" FOREIGN KEY ("documentId") REFERENCES "knowledge_documents"("id") ON DELETE CASCADE);
CREATE UNIQUE INDEX "knowledge_chunks_documentId_ordinal_indexVersion_key" ON "knowledge_chunks"("documentId","ordinal","indexVersion");
CREATE TABLE "knowledge_ingestion_jobs" ("id" TEXT PRIMARY KEY NOT NULL,"sourceId" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'queued',"phase" TEXT NOT NULL DEFAULT 'queued',"processed" INTEGER NOT NULL DEFAULT 0,"total" INTEGER,"errorCode" TEXT,"cancelRequested" BOOLEAN NOT NULL DEFAULT false,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" DATETIME NOT NULL,CONSTRAINT "knowledge_ingestion_jobs_sourceId_fkey" FOREIGN KEY ("sourceId") REFERENCES "knowledge_sources"("id") ON DELETE CASCADE);
CREATE INDEX "knowledge_ingestion_jobs_sourceId_createdAt_idx" ON "knowledge_ingestion_jobs"("sourceId","createdAt");
CREATE TABLE "knowledge_ingestion_events" ("id" INTEGER PRIMARY KEY AUTOINCREMENT,"jobId" TEXT NOT NULL,"seq" INTEGER NOT NULL,"type" TEXT NOT NULL,"payload" JSONB NOT NULL,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "knowledge_ingestion_events_jobId_fkey" FOREIGN KEY ("jobId") REFERENCES "knowledge_ingestion_jobs"("id") ON DELETE CASCADE);
CREATE UNIQUE INDEX "knowledge_ingestion_events_jobId_seq_key" ON "knowledge_ingestion_events"("jobId","seq");
